 "content": "def transform(grid):
    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])
    # Identify inverted V motifs (top point above two lower arms).
    motifs=[]
    for r in range(R-1):
        for c in range(1,C-1):
            if grid[r][c]==2 and grid[r+1][c-1]==2 and grid[r+1][c+1]==2:
                motifs.append((r,c))
    # Motifs in each horizontal band form the endpoints of horizontal bridges;
    # the left and right endpoint V bases are colored in their gap.
    byrow={}
    for r,c in motifs: byrow.setdefault(r,[]).append(c)
    for r,cs in byrow.items():
        cs.sort()
        for a,b in zip(cs,cs[1:]):
            for x in range(a+1,b):
                if grid[r+1][x]==0: out[r+1][x]=1
    # A vertical bridge descends from the central motif where horizontal bars meet.
    if motifs:
        # Select a central motif participating in bridge patterns and connect down to next motif.
        for r,c in motifs:
            if r+1<R and any(x==c for rr,x in motifs if rr>r):
                nr=min(rr for rr,x in motifs if rr>r and x==c)
                for y in range(r+2,nr):
                    if grid[y][c]==0: out[y][c]=1
    return out
